        var receiver = Result.Failure<int>(other);
        var outcome = receiver.Ensure(x => { predicateCalls++; return x > 1; }, x => { messageFactoryCalls++; return "Too small."; });

        Assert.Same(other, outcome.GetError());
        Assert.Equal(0, predicateCalls);
        Assert.Equal(0, messageFactoryCalls);
